import pytest


def settings(keys: list[str], values: list[str]) -> list[str]:
    """Overlay the given settings on the built-in defaults and return the values.

    The defaults are mode="fast" and level="3". For each index i, keys[i] is
    set to values[i]. If a key appears more than once, the last value wins.

    The result holds the value of "mode", then the value of "level", then the
    values of any other keys in the order each key first appears in `keys`.

    Raises ValueError if keys and values differ in length.
    """
    if len(keys) != len(values):
        raise ValueError("keys and values must have the same length")
    merged: dict[str, str] = {"mode": "fast", "level": "3"}
    for k, v in zip(keys, values, strict=True):
        merged[k] = v
    return list(merged.values())


def test_defaults_only() -> None:
    assert settings([], []) == ["fast", "3"]


def test_override_mode() -> None:
    assert settings(["mode"], ["slow"]) == ["slow", "3"]


def test_override_level() -> None:
    assert settings(["level"], ["9"]) == ["fast", "9"]


def test_override_both_in_reverse_order() -> None:
    assert settings(["level", "mode"], ["1", "safe"]) == ["safe", "1"]


def test_extra_keys_follow_in_given_order() -> None:
    assert settings(["z", "mode", "a"], ["1", "slow", "2"]) == ["slow", "3", "1", "2"]


def test_duplicate_keys_last_value_wins_first_position_kept() -> None:
    assert settings(["a", "b", "a"], ["1", "2", "3"]) == ["fast", "3", "3", "2"]


def test_duplicate_mode() -> None:
    assert settings(["mode", "mode"], ["x", "y"]) == ["y", "3"]


def test_length_mismatch_raises() -> None:
    with pytest.raises(ValueError):
        settings(["a", "b"], ["1"])
    with pytest.raises(ValueError):
        settings(["a"], ["1", "2"])
